        from app.factory.build.rule_decision import BUDGET_RESET_KEY

        events = list(self.ledger.events()) if self.ledger.exists() else []
        for index in range(len(events) - 1, -1, -1):
            if (events[index].payload or {}).get(BUDGET_RESET_KEY):
