The Store's ``analytics`` block is action-dispatched: ``track_event`` records
one named observation against a reference, ``get_metrics`` reports what has
been recorded so far. This offline fallback keeps the same action contract and
the same refusal (``metric and value required``) over an in-process series, so
a capability's metrics calls answer with no block store and no collector.
"""

from __future__ import annotations

from typing import Any, Dict, List, Optional

from app.local_blocks._common import Shim, error, ok, run_block

AUTHORED_BY = "codewhale exec"

BLOCK_ID = "analytics"

#: The operations this block answers. Anything else is refused by name.
ACTIONS = ("track_event", "get_metrics")

_EVENTS: List[Dict[str, Any]] = []


def reset() -> None:
    _EVENTS.clear()


def events() -> List[Dict[str, Any]]:
    return list(_EVENTS)


def _operation(action: Optional[str], data: Dict[str, Any]) -> str:
    """The operation this call names.

    The keyword wins when it is given -- an unknown one is refused, never
    silently replaced. Without a keyword, an operation the record itself
    carries is honoured only when it names a real operation for this block
    (a domain field that happens to be called ``action`` is not an operation).
    """
    explicit = str(action).strip() if isinstance(action, str) else ""
    if explicit:
        return explicit
    for key in ("operation", "action"):
        name = str(data.get(key) or "").strip()
        if name in ACTIONS:
            return name
    return "track_event"


class Block(Shim):
    BLOCK_ID = BLOCK_ID
    DEFAULT_ACTION = "track_event"

    def handle(self, input_data: Any, action: Optional[str] = None,
               params: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        data = dict(input_data) if isinstance(input_data, dict) else {}
        call = _operation(action, data)
        if call == "track_event":
            metric = str(data.get("metric") or data.get("metric_name") or "").strip()
            value = data.get("value", data.get("metric_value"))
            if not metric or isinstance(value, bool) or not isinstance(value, (int, float)):
                return error(BLOCK_ID, call, "metric and value required")
            _EVENTS.append({
                "metric": metric,
                "value": float(value),
                "reference": str(data.get("reference") or ""),
            })
            return ok(BLOCK_ID, call, {"tracked": True, "metric": metric, "value": float(value)})
        if call == "get_metrics":
            metrics: Dict[str, float] = {}
            counts: Dict[str, int] = {}
            for event in _EVENTS:
                metrics[event["metric"]] = metrics.get(event["metric"], 0.0) + event["value"]
                counts[event["metric"]] = counts.get(event["metric"], 0) + 1
            return ok(BLOCK_ID, call, {"metrics": metrics, "counts": counts})
        return error(BLOCK_ID, call, "Unknown action: %s" % call)


class_instance = Block()


def run(**kwargs: Any) -> Dict[str, Any]:
    return run_block(BLOCK_ID, class_instance, **kwargs)
